export interface LotusChessPieceProps {
  type: PieceSymbol;
  color: Color;
  className?: string;
}

export const LotusChessPiece: React.FC<LotusChessPieceProps> = React.memo(({
  type,
  color,
  className = 'w-full h-full'
}) => {
  if (color === 'w') {
    switch (type) {
      case 'p': return <LotusWhitePawn className={className} />;
      case 'r': return <LotusWhiteRook1 className={className} />;
      case 'n': return <LotusWhiteKnight1 className={className} />;
      case 'b': return <LotusWhiteBishop1 className={className} />;
      case 'q': return <LotusWhiteQueen className={className} />;
      case 'k': return <LotusWhiteKing className={className} />;
      default: return null;
    }
  } else {
    switch (type) {
      case 'p': return <LotusBlackPawn className={className} />;
      case 'r': return <LotusBlackRook1 className={className} />;
      case 'n': return <LotusBlackKnight1 className={className} />;
      case 'b': return <LotusBlackBishop1 className={className} />;
      case 'q': return <LotusBlackQueen className={className} />;
      case 'k': return <LotusBlackKing className={className} />;
      default: return null;
    }
  }
});
